export { useAppDraftSession } from "@/lib/use-app-draft-session"

function capture(session: AppDraftSession) {
  const map = getAdminMapInstance()
  if (map?.id === session.mapId) session.capture(map.getData!() as any)
}

const iconActionClass = "bg-transparent text-muted-foreground shadow-none transition-colors hover:bg-transparent hover:text-foreground focus-visible:bg-transparent focus-visible:text-foreground data-[state=open]:text-foreground dark:hover:bg-transparent"

// A save spinner, draft switch or toolbar remount must not repeat the outage toast.
const notifiedOfflineSessions = new WeakSet<AppDraftSession>()
const offlineSaveMessage = "Saved on this device. Waiting to sync with the server."

function IconAction({ label, tooltip = label, children, className, ...props }: {
  label: string; tooltip?: string; children: ReactNode
} & Omit<React.ComponentProps<typeof Button>, "children">) {
  return <Tooltip><TooltipTrigger asChild><Button type="button" size="icon-xs" variant="ghost" aria-label={label} className={cn(iconActionClass, className)} {...props}>{children}</Button></TooltipTrigger><TooltipContent>{tooltip}</TooltipContent></Tooltip>
}

export function AppDraftConflictActions({ disabled, onPull, onBranch }: {
  disabled: boolean; onPull: () => void; onBranch: () => void
}) {
  return <div className="flex shrink-0 flex-wrap gap-2">
    <Button type="button" size="xs" variant="outline" disabled={disabled} onClick={onPull}><GitPullRequestArrow aria-hidden="true" />Pull changes</Button>
    <Button type="button" size="xs" variant="outline" disabled={disabled} onClick={onBranch}><GitBranch aria-hidden="true" />Branch into a new draft</Button>
  </div>
}

function OldEditorButton({ href, size = "xs", className }: { href: string; size?: "xs" | "sm"; className?: string }) {
  return <Button asChild size={size} variant="secondary" className={cn("bg-blue-50 font-semibold text-blue-700 hover:bg-blue-100 dark:bg-blue-950 dark:text-blue-200 dark:hover:bg-blue-900", className)}>
    <a href={href}><ExternalLink aria-hidden="true" />Open in old editor</a>
  </Button>
}

const actionsClass = "pointer-events-none absolute right-1 top-1/2 -translate-y-1/2 flex items-center gap-0.5 opacity-0 transition-opacity group-hover:pointer-events-auto group-hover:opacity-100 group-focus-within:pointer-events-auto group-focus-within:opacity-100 [@media(hover:none)]:pointer-events-auto [@media(hover:none)]:opacity-100"
const actionSpaceClass = "pr-2 group-hover:pr-28 group-focus-within:pr-28 [@media(hover:none)]:pr-28"

function InlineNameInput({ title, label, disabled, onSave, onCancel }: {
  title: string; label: string; disabled: boolean; onSave: (title: string) => Promise<boolean>; onCancel: () => void
}) {
  const [value, setValue] = useState(title)
  const pending = useRef(false)
  const finished = useRef(false)
  async function save() {
    if (pending.current || finished.current) return
    const name = value.trim()
    if (!name || name === title) { finished.current = true; onCancel(); return }
    // Enter may also blur the disabled input. Submit the rename only once.
    pending.current = true
    try { if (await onSave(name)) finished.current = true }
    finally { pending.current = false }
  }
  return <Input aria-label={label} autoFocus disabled={disabled} value={value}
    onFocus={event => event.currentTarget.select()} onChange={event => setValue(event.target.value)}
    onBlur={() => void save()} onKeyDown={event => {
      if (event.nativeEvent.isComposing) return
      if (event.key === "Enter") { event.preventDefault(); event.stopPropagation(); void save() }
      if (event.key === "Escape") {
        event.preventDefault(); event.stopPropagation()
        if (!pending.current) { finished.current = true; onCancel() }
      }
    }} />
}

export function AppVersions({ session, disabled, onReplace, onCheckout, onPull, open: controlledOpen, onOpenChange, overflowAnchor }: {
  session: AppDraftSession; disabled: boolean; onReplace: () => void; onRevert?: () => void; onCheckout: (snapshot: AppSnapshot) => void; onPull: () => void
  open?: boolean; onOpenChange?: (open: boolean) => void; overflowAnchor?: RefObject<HTMLButtonElement | null>
}) {
  const [internalOpen, setInternalOpen] = useState(false)
  const open = controlledOpen ?? internalOpen
  const setOpen = onOpenChange ?? setInternalOpen
  const pullingConfirmation = useRef(false)
  const dismissedFromPreview = useRef(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [renaming, setRenaming] = useState<{ kind: "draft" | "version"; id: number; title: string } | null>(null)
  const [deleting, setDeleting] = useState<{ id: number; title: string } | null>(null)
  const [comparison, setComparison] = useState<{ title: string; changes: ReturnType<typeof appOptionsDelta> } | null>(null)
  const active = session.active
  const migrationDraftId = active?.draft.migration ? active.draft.id : null
  const lastMigrationEntry = useRef<string | null>(null)
  const [migrationNotice, setMigrationNotice] = useState<number | null>(null)
  useEffect(() => {
    if (!session.ready) return
    const entry = migrationDraftId === null ? null : `${session.mapId}:${migrationDraftId}`
    if (entry === null) { lastMigrationEntry.current = null; setMigrationNotice(null); return }
    if (disabled || entry === lastMigrationEntry.current) return
    lastMigrationEntry.current = entry
    setOpen(false)
    setMigrationNotice(migrationDraftId)
  }, [session, session.ready, migrationDraftId, disabled, setOpen])
  const conflictMessage = "The server has a newer version of this draft. Your local copy is retained."
  const saveError = active?.conflicted ? conflictMessage
    : active?.dirty && !active.localSaved ? active.localError : undefined
  const draftSaved = active && (active.localSaved || !active.dirty)
  const savedOffline = session.offline && active?.localSaved
  const saveStatus = session.busy ? "Saving draft…" : saveError ?? (!draftSaved ? "Saving draft…"
    : savedOffline ? offlineSaveMessage : "Draft saved")
  const offline = session.offline
  useEffect(() => {
    if (!offline) {
      if (notifiedOfflineSessions.delete(session)) toast.success("Connection to the server restored.")
    } else if (saveStatus === offlineSaveMessage && !notifiedOfflineSessions.has(session)) {
      notifiedOfflineSessions.add(session)
      toast.info(offlineSaveMessage)
    }
  }, [session, offline, saveStatus])
  const locked = busy || disabled || session.busy || session.transitioning
  const remoteLocked = locked || session.offline
  async function perform(action: () => Promise<void>, replace = false): Promise<boolean> {
    capture(session)
    setBusy(true); setError(null)
    if (replace) session.setTransitioning(true)
    try { await action(); if (replace) onReplace(); return true }
    catch (error) { setError(error instanceof Error ? error.message : String(error)); return false }
    finally { setBusy(false); if (replace) session.setTransitioning(false) }
  }
  const shortcode = (versionId: number) => versionId === session.publishedVersionId
    ? `[mapsvg id="${session.mapId}"]` : `[mapsvg id="${session.mapId}" version="${versionId}"]`
  async function copyShortcode(versionId: number) {
    setError(null)
    try { await navigator.clipboard.writeText(shortcode(versionId)); toast.success("Shortcode copied") }
    catch { setError("Could not copy shortcode. Check your browser clipboard permissions.") }
  }
  async function compare(id: number) {
    await perform(async () => {
      const copy = session.copies.get(id)!
      const snapshot = structuredClone(copy.snapshot)
      const publishedId = session.publishedVersionId
      const publishedOptions = publishedId === null ? {} : (await session.versionSnapshot(publishedId)).options
      setComparison({ title: copy.draft.title, changes: appOptionsDelta(publishedOptions, snapshot.options) })
      setOpen(false)
    })
  }
  function newDraft(versionId?: number, recovery?: AppSnapshot) {
    void perform(() => session.create(undefined, versionId, recovery), true)
  }
  useEffect(() => { if (open && session.ready && !session.offline) void session.refreshHistory().catch(error => setError(String(error))) }, [open, session])
  useEffect(() => {
    if (!open) return
    const dismiss = () => {
      dismissedFromPreview.current = true
      setOpen(false); setRenaming(null)
    }
    window.addEventListener(PREVIEW_POINTER_DOWN, dismiss)
    return () => window.removeEventListener(PREVIEW_POINTER_DOWN, dismiss)
  }, [open, setOpen])
  const publicVersions = session.versions.filter(version => version.published_at || version.kind === "publication" || version.id === session.publishedVersionId)
  const published = publicVersions.find(version => version.id === session.publishedVersionId)
  const history = publicVersions.filter(version => version.id !== session.publishedVersionId)

  function versionRow(version: (typeof publicVersions)[number], current: boolean) {
    const editing = renaming?.kind === "version" && renaming.id === version.id
    return <div key={version.id} data-version-id={version.id} data-version-status={current ? "published" : "history"} className={cn("group relative flex min-h-8 min-w-0 items-center gap-2 rounded-md pl-2 text-xs hover:bg-muted/50", editing ? "pr-2" : "pr-2 hover:pr-28 focus-within:pr-28 [@media(hover:none)]:pr-28")}>
      {editing ? <InlineNameInput label="Version name" title={renaming.title} disabled={busy} onCancel={() => setRenaming(null)}
        onSave={async name => { const saved = await perform(() => session.renameVersion(version.id, name, renaming.title)); if (saved) setRenaming(null); return saved }} />
        : <span className="min-w-0 flex-1 truncate font-normal" title={version.title}>{version.title}</span>}
      <Badge variant="secondary" className={cn("shrink-0 text-[10px]", current && "border-green-200 bg-green-50 text-green-700 dark:border-green-800 dark:bg-green-950 dark:text-green-300", !editing && "group-hover:hidden group-focus-within:hidden [@media(hover:none)]:hidden")}>{version.engine === 8 ? "v8 · " : ""}version {version.id}</Badge>
      {!editing ? <div className={actionsClass}>
        {current
          ? <IconAction label="Unpublish" disabled={remoteLocked} onClick={() => void perform(() => session.unpublish(version.id))}><ArrowDownToLine /></IconAction>
          : <IconAction label="Publish version" tooltip="Publish" disabled={remoteLocked} onClick={() => void perform(async () => { onCheckout(await session.checkout(version.id)) })}><ArrowUpFromLine /></IconAction>}
        <IconAction label="Rename version" tooltip="Rename" disabled={remoteLocked} onClick={() => { setRenaming({ kind: "version", id: version.id, title: version.title }); setError(null) }}><Pencil /></IconAction>
        <IconAction label="Branch in new draft" disabled={remoteLocked} onClick={() => newDraft(version.id)}><GitBranch /></IconAction>
        <IconAction label="Copy shortcode" tooltip={shortcode(version.id)} onClick={() => void copyShortcode(version.id)}><Copy /></IconAction>
      </div> : null}
    </div>
  }

  return <>
    <Popover open={open} onOpenChange={value => { setOpen(value); if (!value) setRenaming(null) }}>
      {overflowAnchor ? <PopoverAnchor virtualRef={overflowAnchor} /> : null}
      <PopoverTrigger asChild>
        <Button type="button" size="xs" variant="outline" aria-label="Versions" className="gap-2" disabled={disabled || !session.ready}>
          <Tooltip><TooltipTrigger asChild><span className="inline-flex"><Clock /></span></TooltipTrigger><TooltipContent side="bottom">Drafts and version history</TooltipContent></Tooltip>
          {active ? <Tooltip><TooltipTrigger asChild>
            <span role="status" aria-label={saveStatus} data-slot="draft-save-status" className={cn("inline-flex text-muted-foreground", !session.busy && saveError && "text-amber-600")}>
              {session.busy || !saveError && !draftSaved ? <LoaderCircle className="animate-spin" aria-hidden="true" /> : saveError ? <AlertCircle aria-hidden="true" /> : savedOffline ? <CloudOff aria-hidden="true" /> : <Check aria-hidden="true" />}
            </span>
          </TooltipTrigger><TooltipContent side="bottom">{saveStatus}</TooltipContent></Tooltip> : null}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" onEscapeKeyDown={event => { if (renaming !== null) event.preventDefault() }} onCloseAutoFocus={event => {
        if (comparison || deleting || pullingConfirmation.current || dismissedFromPreview.current) event.preventDefault()
        else if (overflowAnchor) { event.preventDefault(); overflowAnchor.current?.focus() }
        pullingConfirmation.current = false; dismissedFromPreview.current = false
      }} className="w-[500px] max-w-[calc(100vw-2rem)] p-0">
        {session.offline ? <p role="status" className="px-3 pt-2 text-xs text-amber-700">Server unavailable. Editing local drafts; synchronization will retry automatically.</p> : null}
        {error ? <p role="alert" className="px-3 pt-2 text-xs text-destructive">{error}</p> : null}
        <div className="grid grid-cols-2 divide-x">
          <section className="min-w-0 p-2" aria-label="Drafts">
            <div className="mb-1 flex h-6 items-center justify-between px-1"><strong className="text-xs leading-4 font-semibold">Drafts</strong><Tooltip><TooltipTrigger asChild><span className="inline-flex"><Button variant="secondary" size="xs" disabled={remoteLocked} onClick={() => newDraft()}><Plus aria-hidden="true" />New</Button></span></TooltipTrigger><TooltipContent>Create new draft</TooltipContent></Tooltip></div>
            <div className="max-h-[360px] space-y-0.5 overflow-y-auto">
              {[...session.copies.values()].sort((a, b) => b.draft.id - a.draft.id).map(copy => <div key={copy.draft.id} data-draft-id={copy.draft.id} data-active={copy.draft.id === session.activeId} className={`group relative rounded-md text-xs ${copy.draft.id === session.activeId ? "bg-muted" : "hover:bg-muted/50"}`}>
                {renaming?.kind === "draft" && renaming.id === copy.draft.id ? <div className="flex min-h-8 items-center gap-2 px-2">
                  <InlineNameInput label="Draft name" title={renaming.title} disabled={busy} onCancel={() => setRenaming(null)}
                    onSave={async name => { const saved = await perform(() => session.rename(copy.draft.id, name)); if (saved) setRenaming(null); return saved }} />
                  {copy.draft.id === session.activeId ? <Check className="size-3.5 shrink-0" aria-label="Editing" /> : null}
                </div> : <>
                <button type="button" aria-label={`Edit draft ${copy.draft.title}`} aria-pressed={copy.draft.id === session.activeId} disabled={locked}
                  className={cn("flex min-h-8 w-full min-w-0 cursor-pointer items-center gap-2 rounded-md pl-2 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-default", actionSpaceClass)}
                  onClick={() => { if (copy.draft.id !== session.activeId) void perform(() => session.select(copy.draft.id), true); else if (copy.draft.migration) { setOpen(false); setMigrationNotice(copy.draft.id) } }}>
                  <span className="min-w-0 truncate font-normal" title={copy.draft.title}>{copy.draft.title}</span>
                  {copy.draft.migration ? <Badge variant="secondary" className="shrink-0 text-[10px] group-hover:hidden group-focus-within:hidden">Migration</Badge> : null}
                  {copy.draft.id === session.activeId ? <Check className="size-3.5 shrink-0" aria-label="Editing" /> : null}
                  {copy.conflicted ? <AlertCircle className="size-3.5 shrink-0 text-destructive" role="img" aria-label={conflictMessage}><title>{conflictMessage}</title></AlertCircle> : null}
                </button>
                <div className={actionsClass}>
                  <IconAction label="Publish draft" disabled={remoteLocked || copy.conflicted} onClick={() => void perform(async () => { const snapshot = structuredClone(copy.snapshot); await session.publish(snapshot, copy.draft.id); onCheckout(snapshot) })}><ArrowUpFromLine /></IconAction>
                  <IconAction label="Rename draft" disabled={remoteLocked || copy.conflicted} onClick={() => { setRenaming({ kind: "draft", id: copy.draft.id, title: copy.draft.title }); setError(null) }}><Pencil /></IconAction>
                  <IconAction label="Compare with Published" disabled={remoteLocked} onClick={() => void compare(copy.draft.id)}><Diff /></IconAction>
                  <IconAction label="Delete draft" disabled={remoteLocked} onClick={() => { capture(session); setError(null); setDeleting({ id: copy.draft.id, title: copy.draft.title }); setOpen(false) }}><Trash2 /></IconAction>
                </div>
                </>}
              </div>)}
              {session.copies.size === 0 ? <p className="px-1 py-2 text-xs text-muted-foreground">No drafts</p> : null}
            </div>
            {active?.conflicted ? <div className="mt-2 space-y-2">
              <p className="text-xs text-muted-foreground">Pull changes replaces local edits with the server copy.</p>
              <AppDraftConflictActions disabled={remoteLocked}
                onPull={() => { pullingConfirmation.current = true; setOpen(false); onPull() }} onBranch={() => newDraft()} />
            </div> : null}
            {session.recoveries.map(item => <Button key={item.key} className="mt-2 max-w-full" size="xs" variant="outline" disabled={remoteLocked} onClick={() => newDraft(undefined, item.snapshot)}>Recover: {item.title}</Button>)}
            {active?.serverError || active?.localError ? <div className="mt-2 text-xs text-destructive" role="alert">{active.conflicted ? conflictMessage : active.serverError ?? active.localError}{active.dirty && !active.conflicted ? <Button variant="ghost" size="xs" disabled={locked} onClick={() => void perform(() => session.flush())}>Retry save</Button> : null}</div> : null}
          </section>
          <div className="min-w-0 p-2">
            <section aria-label="Published">
              <div className="mb-1 flex h-6 items-center px-1"><strong className="text-xs leading-4 font-semibold">Published</strong></div>
              {published ? versionRow(published, true) : <p className="px-1 py-2 text-xs text-muted-foreground">No published version</p>}
              {published?.engine === 8 && published.old_editor_url ? <OldEditorButton href={published.old_editor_url} className="mt-1 ml-2" /> : null}
            </section>
            <section aria-label="History" className="mt-2 border-t pt-2">
              <div className="mb-1 flex h-6 items-center px-1"><strong className="text-xs leading-4 font-semibold">History</strong></div>
              <div className="max-h-[280px] space-y-0.5 overflow-y-auto">
                {history.map(version => versionRow(version, false))}
                {history.length === 0 ? <p className="px-1 py-2 text-xs text-muted-foreground">No previous publications</p> : null}
              </div>
            </section>
          </div>
        </div>
      </PopoverContent>
    </Popover>
    <Dialog open={migrationNotice !== null && migrationNotice === migrationDraftId} onOpenChange={value => { if (!value) setMigrationNotice(null) }}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>Review your migrated draft before publishing</DialogTitle>
          <DialogDescription>This draft is a separate v9 copy of your v8 map.</DialogDescription>
        </DialogHeader>
        <div className="space-y-3 text-sm">
          <p>{published?.engine === 8 ? <>Your website is still showing the published v8 map. Editing this draft does not change it. To edit v8, use <span className="inline-flex items-center gap-1 font-semibold"><ExternalLink className="size-3.5" aria-hidden="true" />Open in old editor</span> in Versions → Published.</> : "Editing this draft does not change the published map."}</p>
          <p>Migration may change how your map works. Some issues may not be obvious in the editor, especially with custom code, templates, filters and interactions.</p>
          <p>Ask the built-in AI assistant to help adapt your v8 JavaScript event handlers, templates and CSS to v9 while preserving your map's existing behavior. It has access to the MapSVG JavaScript API documentation. Test the result in Preview and describe any problems to the assistant so it can make further corrections. Repeat until everything works as expected before publishing.</p>
          <p>Before you Publish, click <span className="inline-flex items-center gap-1 font-semibold"><ExternalLink className="size-3.5" aria-hidden="true" />Preview</span> and carefully test every feature on the front-end preview, including desktop and mobile layouts, links, filters and click actions.</p>
          <p>Changes saved in the old editor are <strong>not copied into this draft</strong>. Publishing this draft replaces the current published settings, including any later changes made in the old editor.</p>
          <p>If you publish v9 by mistake, open <span className="inline-flex items-center gap-1 font-semibold"><Clock className="size-3.5" aria-hidden="true" />Versions</span> → History and click <span className="inline-flex items-center gap-1 font-semibold"><ArrowUpFromLine className="size-3.5" aria-hidden="true" />Publish</span> on the previous v8 version to restore it. Your v9 draft is kept; shared Database records keep their current data.</p>
        </div>
        <DialogFooter className="gap-2">
          {published?.engine === 8 && published.old_editor_url ? <OldEditorButton href={published.old_editor_url} size="sm" /> : null}
          <Button size="sm" onClick={() => setMigrationNotice(null)}>Continue editing draft</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
    <Dialog open={comparison !== null} onOpenChange={value => { if (!value) { setComparison(null); setOpen(true) } }}>
      <DialogContent aria-describedby={undefined} className="flex max-h-[calc(100dvh-2rem)] flex-col gap-3 overflow-hidden p-4 sm:max-w-3xl">
        <DialogHeader className="shrink-0 pr-6"><DialogTitle className="text-base">{comparison?.title} — changes</DialogTitle></DialogHeader>
        {/* Keep wheel/touch events inside the ShadowRoot: Radix's document scroll lock
            sees a retargeted host instead of this scroll region. Native scrolling stays intact. */}
        <div role="region" aria-label="Parameter comparison" tabIndex={0}
          className="max-h-[65dvh] min-h-0 overflow-auto overscroll-contain rounded-md border outline-none focus-visible:ring-2 focus-visible:ring-ring [&>[data-slot=table-container]]:overflow-visible"
          onWheel={event => event.stopPropagation()} onTouchMove={event => event.stopPropagation()}>
          <Table className="table-fixed text-xs" aria-label="Changes from Published">
            <TableHeader className="sticky top-0 z-10 bg-muted"><TableRow>
              <TableHead scope="col" className="h-8 w-1/3">Parameter</TableHead>
              <TableHead scope="col" className="h-8 w-1/3 border-l">Published</TableHead>
              <TableHead scope="col" className="h-8 w-1/3 border-l">Draft</TableHead>
            </TableRow></TableHeader>
            <TableBody>
              {comparison?.changes.length === 0 ? <TableRow><TableCell colSpan={3} className="py-6 text-center text-muted-foreground">No changes</TableCell></TableRow> : comparison?.changes.map(change => <TableRow key={change.path}>
                <TableCell className="px-2 py-1.5 align-top font-mono whitespace-normal [overflow-wrap:anywhere]">{change.path}</TableCell>
                <TableCell className="border-l bg-red-500/5 px-2 py-1.5 align-top whitespace-normal"><pre className="whitespace-pre-wrap [overflow-wrap:anywhere]">{change.before === undefined ? "(not set)" : JSON.stringify(change.before, null, 2)}</pre></TableCell>
                <TableCell className="border-l bg-green-500/5 px-2 py-1.5 align-top whitespace-normal"><pre className="whitespace-pre-wrap [overflow-wrap:anywhere]">{change.after === undefined ? "(not set)" : JSON.stringify(change.after, null, 2)}</pre></TableCell>
              </TableRow>)}
            </TableBody>
          </Table>
        </div>
      </DialogContent>
    </Dialog>
    <AlertDialog open={deleting !== null} onOpenChange={value => { if (!value && !busy) { setDeleting(null); setOpen(true) } }}>
      <AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Delete draft?</AlertDialogTitle><AlertDialogDescription>“{deleting?.title}” will be deleted, including its unpublished changes. Published versions are kept.</AlertDialogDescription></AlertDialogHeader>
        {error ? <p role="alert" className="text-xs text-destructive">{error}</p> : null}
        <AlertDialogFooter><AlertDialogCancel size="sm" disabled={busy}>Cancel</AlertDialogCancel><AlertDialogAction size="sm" variant="destructive" disabled={busy} onClick={event => { event.preventDefault(); if (deleting) void perform(async () => { await session.deleteDraft(deleting.id); setDeleting(null); setOpen(true) }, deleting.id === session.activeId) }}>Delete</AlertDialogAction></AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  </>
}
