/** Child-document events do not bubble to the editor's outside-click handlers. */
export const PREVIEW_POINTER_DOWN = "mapsvg:preview-pointerdown"

export function bridgePreviewPointerDown(doc: Document, lifetime: AbortSignal): void {
  if (lifetime.aborted) return
  const notify = () => window.dispatchEvent(new CustomEvent(PREVIEW_POINTER_DOWN))
  // Capture before runtime handlers can stop propagation; leave the original event untouched.
  doc.addEventListener("pointerdown", notify, true)
  lifetime.addEventListener("abort", () => doc.removeEventListener("pointerdown", notify, true), { once: true })
}
