export type AppOptionChange = { path: string; before: unknown; after: unknown }

/** Authoring options only; recursively compare dictionaries, with JSON-pointer paths for dictionaries and array entries. */
export function appOptionsDelta(main: Record<string, unknown>, draft: Record<string, unknown>): AppOptionChange[] {
  const changes: AppOptionChange[] = []
  function compare(before: unknown, after: unknown, path: string) {
    if (before === after) return
    const dictionary = (value: unknown): value is Record<string, unknown> => value !== null && typeof value === "object" && !Array.isArray(value)
    if (dictionary(before) && dictionary(after)) {
      for (const key of [...new Set([...Object.keys(before), ...Object.keys(after)])].sort()) {
        if (!path && key === "useShadowRoot") continue
        compare(before[key], after[key], `${path}/${key.replace(/~/g, "~0").replace(/\//g, "~1")}`)
      }
    } else if (Array.isArray(before) && Array.isArray(after)) {
      // Walk array entries too, avoiding noisy differences from object-key order inside arrays.
      for (let index = 0; index < Math.max(before.length, after.length); index++) compare(before[index], after[index], `${path}/${index}`)
    } else changes.push({ path, before, after })
  }
  compare(main, draft, "")
  return changes
}
